#[test]
fn test_pg_cast() {
    run_scripts(&[
        ScriptTest {
            name: "pg_cast",
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT castsource::regtype, casttarget::regtype, castcontext FROM "pg_catalog"."pg_cast" WHERE castsource = 'xml'::regtype OR casttarget = 'xml'::regtype ORDER BY castsource::regtype::text, casttarget::regtype::text;"#,
                    expected: Expected::Rows {
                        columns: &[Column("castsource", REGTYPE), Column("casttarget", REGTYPE), Column("castcontext", CHAR)],
                        rows: &[
                            &[T("character"), T("xml"), T("e")],
                            &[T("character varying"), T("xml"), T("e")],
                            &[T("text"), T("xml"), T("e")],
                            &[T("xml"), T("character"), T("a")],
                            &[T("xml"), T("character varying"), T("a")],
                            &[T("xml"), T("text"), T("a")],
                        ],
                        tag: "SELECT 6",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "PG_catalog"."pg_cast";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "PG_catalog.pg_cast" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "pg_catalog"."PG_cast";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "pg_catalog.PG_cast" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT castsource::regtype, casttarget::regtype, castcontext, castmethod FROM PG_catalog.pg_CAST WHERE castsource = 'int4'::regtype AND casttarget = 'int8'::regtype;",
                    expected: Expected::Rows {
                        columns: &[Column("castsource", REGTYPE), Column("casttarget", REGTYPE), Column("castcontext", CHAR), Column("castmethod", CHAR)],
                        rows: &[
                            &[T("integer"), T("bigint"), T("i"), T("f")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

