#[test]
fn test_pg_class_indexes() {
    run_scripts(&[
        ScriptTest {
            name: "pg_class index lookup",
            set_up_script: &[
                "create table t1 (a int primary key, b int not null)",
                "create table t2 (c int primary key, d int not null)",
                "create index on t2 (d)",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT c.oid
FROM pg_catalog.pg_class c 
WHERE c.relname = 't2' and c.relnamespace = 2200 -- public
ORDER BY 1;"#,
                    expected: Expected::Rows {
                        columns: &[Column("oid", OID)],
                        rows: &[
                            &[Oid(16389)],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT c.relname
FROM pg_catalog.pg_class c 
WHERE c.relname > 't' AND c.relname < 't2' AND c.relnamespace = 2200 -- public
AND relkind = 'r'
ORDER BY 1;"#,
                    expected: Expected::Rows {
                        columns: &[Column("relname", NAME)],
                        rows: &[
                            &[T("t1")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT c.relname
FROM pg_catalog.pg_class c 
WHERE c.relname >= 't1' AND c.relname <= 't2' AND c.relnamespace = 2200 -- public
AND relkind = 'r'
ORDER BY 1;"#,
                    expected: Expected::Rows {
                        columns: &[Column("relname", NAME)],
                        rows: &[
                            &[T("t1")],
                            &[T("t2")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT c.relname
FROM pg_catalog.pg_class c 
WHERE c.relname >= 't1' AND c.relname < 't2' AND c.relnamespace = 2200 -- public
AND relkind = 'r'
ORDER BY 1;"#,
                    expected: Expected::Rows {
                        columns: &[Column("relname", NAME)],
                        rows: &[
                            &[T("t1")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT c.relname
FROM pg_catalog.pg_class c 
WHERE c.relname > 't1' AND c.relname <= 't2' AND c.relnamespace = 2200 -- public
AND relkind = 'r'
ORDER BY 1;"#,
                    expected: Expected::Rows {
                        columns: &[Column("relname", NAME)],
                        rows: &[
                            &[T("t2")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT c.relname
FROM pg_catalog.pg_class c 
WHERE c.relname > 't1' AND c.relname <= 't2' AND c.relnamespace > 2199 AND c.relnamespace < 2201 -- public
AND relkind = 'r'
ORDER BY 1;"#,
                    expected: Expected::Rows {
                        columns: &[Column("relname", NAME)],
                        rows: &[
                            &[T("t2")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT c.relname
FROM pg_catalog.pg_class c 
WHERE c.oid = 1496157034
ORDER BY 1;"#,
                    expected: Expected::Rows {
                        columns: &[Column("relname", NAME)],
                        rows: &[],
                        tag: "SELECT 0",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT c.relname
FROM pg_catalog.pg_class c 
WHERE c.oid = '1496157034'
ORDER BY 1;"#,
                    expected: Expected::Rows {
                        columns: &[Column("relname", NAME)],
                        rows: &[],
                        tag: "SELECT 0",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT c.relname
FROM pg_catalog.pg_class c 
WHERE c.oid IN (1496157034, 1496157035) 
ORDER BY 1;"#,
                    expected: Expected::Rows {
                        columns: &[Column("relname", NAME)],
                        rows: &[],
                        tag: "SELECT 0",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT c.relname
FROM pg_catalog.pg_class c 
WHERE c.oid > 1496157033 AND c.oid < 1496157035
ORDER BY 1;"#,
                    expected: Expected::Rows {
                        columns: &[Column("relname", NAME)],
                        rows: &[],
                        tag: "SELECT 0",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT relname from pg_catalog.pg_class order by oid limit 1;",
                    expected: Expected::Rows {
                        columns: &[Column("relname", NAME)],
                        rows: &[
                            &[T("pg_foreign_data_wrapper_oid_index")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"EXPLAIN SELECT c.oid
FROM pg_catalog.pg_class c 
WHERE c.relname = 't2' and c.relnamespace = 2200
ORDER BY 1;"#,
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::IndexScan { table: "pg_class", columns: &["relname", "relnamespace"], ranges: r#"[{[t2, t2], [{Namespace:["public"]}, {Namespace:["public"]}]}]"# }]),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"EXPLAIN SELECT c.relname
FROM pg_catalog.pg_class c 
WHERE c.relname > 't' AND c.relname < 't2' AND c.relnamespace = 2200 -- public
AND relkind = 'r'
ORDER BY 1;"#,
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::IndexScan { table: "pg_class", columns: &["relname", "relnamespace"], ranges: r#"[{(t, t2), [{Namespace:["public"]}, {Namespace:["public"]}]}]"# }]),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"EXPLAIN SELECT c.relname
FROM pg_catalog.pg_class c 
WHERE c.oid = 1496157034
ORDER BY 1;"#,
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::IndexScan { table: "pg_class", columns: &["oid"], ranges: r#"[{[{Table:["public","t2"]}, {Table:["public","t2"]}]}]"# }]),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"EXPLAIN SELECT c.relname
FROM pg_catalog.pg_class c 
WHERE c.oid > 1496157033 AND c.oid < 1496157035
ORDER BY 1;"#,
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::IndexScan { table: "pg_class", columns: &["oid"], ranges: r#"[{({OID:["1496157033"]}, {OID:["1496157035"]})}]"# }]),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"EXPLAIN SELECT c.relname
FROM pg_catalog.pg_class c 
WHERE c.oid IN (1496157034, 1496157035) 
ORDER BY 1;"#,
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::IndexScan { table: "pg_class", columns: &["oid"], ranges: r#"[{[{Table:["public","t2"]}, {Table:["public","t2"]}]}, {[{OID:["1496157035"]}, {OID:["1496157035"]}]}]"# }]),
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "join on pg_class",
            set_up_script: &[
                "create table t1 (a int primary key, b int not null)",
                "create table t2 (c int primary key, d int not null)",
                "create index on t2 (d)",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT c.relname, a.attname 
FROM pg_catalog.pg_class c 
    JOIN pg_catalog.pg_attribute a 
        ON c.oid = a.attrelid 
WHERE c.relkind = 'r' AND a.attnum > 0 
  AND NOT a.attisdropped
  AND c.relname = 't2'
ORDER BY 1,2;"#,
                    expected: Expected::Rows {
                        columns: &[Column("relname", NAME), Column("attname", NAME)],
                        rows: &[
                            &[T("t2"), T("c")],
                            &[T("t2"), T("d")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"EXPLAIN SELECT c.relname, a.attname
FROM pg_catalog.pg_class c
    JOIN pg_catalog.pg_attribute a
        ON c.oid = a.attrelid
WHERE c.relkind = 'r' AND a.attnum > 0
  AND NOT a.attisdropped
  AND c.relname = 't2'
ORDER BY 1,2;"#,
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::Join { kind: "InnerJoin", left: "pg_attribute", right: "pg_class" }, PlanFact::FullScan { table: "pg_attribute" }, PlanFact::IndexScan { table: "pg_class", columns: &["relname", "relnamespace"], ranges: "[{[t2, t2], [NULL, ∞)}]" }]),
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "left join with nil left result",
            set_up_script: &[
                "create table t1 (a int primary key, b int not null)",
                "create table t2 (c int primary key, d int not null)",
                "create index on t2 (d)",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT n.nspname as "Schema",
  c.relname as "Name",
  pg_catalog.pg_get_userbyid(c.relowner) as "Owner",
 c2.oid::pg_catalog.regclass as "Table"
FROM pg_catalog.pg_class c
     LEFT JOIN pg_catalog.pg_namespace n ON n.oid = c.relnamespace
     LEFT JOIN pg_catalog.pg_index i ON i.indexrelid = c.oid
     LEFT JOIN pg_catalog.pg_class c2 ON i.indrelid = c2.oid
WHERE c.relkind IN ('I','')
 AND NOT c.relispartition
      AND n.nspname <> 'pg_catalog'
      AND n.nspname !~ '^pg_toast'
      AND n.nspname <> 'information_schema'
  AND pg_catalog.pg_table_is_visible(c.oid)
ORDER BY "Schema", "Name""#,
                    expected: Expected::Rows {
                        columns: &[Column("Schema", NAME), Column("Name", NAME), Column("Owner", NAME), Column("Table", REGCLASS)],
                        rows: &[],
                        tag: "SELECT 0",
                    },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: " tables in multiple schemas",
            set_up_script: &[
                "CREATE SCHEMA s1;",
                "CREATE SCHEMA s2;",
                "create schema s3;",
                "CREATE TABLE s2.t (a INT);",
                "CREATE TABLE s1.t (b INT);",
                "CREATE TABLE s3.t (c INT);",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: r#"select relname, nspname FROM pg_catalog.pg_class c 
join pg_catalog.pg_namespace n on c.relnamespace = n.oid
where c.relname = 't' and c.relkind = 'r'
order by 1,2"#,
                    expected: Expected::Rows {
                        columns: &[Column("relname", NAME), Column("nspname", NAME)],
                        rows: &[
                            &[T("t"), T("s1")],
                            &[T("t"), T("s2")],
                            &[T("t"), T("s3")],
                        ],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"select relname, relnamespace FROM pg_catalog.pg_class c 
where c.relname = 't' and c.relkind = 'r'
order by 1,2"#,
                    expected: Expected::Rows {
                        columns: &[Column("relname", NAME), Column("relnamespace", OID)],
                        rows: &[
                            &[T("t"), Oid(16384)],
                            &[T("t"), Oid(16385)],
                            &[T("t"), Oid(16386)],
                        ],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"explain select relname, nspname FROM pg_catalog.pg_class c 
join pg_catalog.pg_namespace n on c.relnamespace = n.oid
where c.relname = 't' and c.relkind = 'r'
order by 1,2"#,
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::Join { kind: "LookupJoin", left: "pg_class", right: "pg_namespace" }, PlanFact::IndexScan { table: "pg_class", columns: &["relname", "relnamespace"], ranges: "[{[t, t], [NULL, ∞)}]" }, PlanFact::IndexScan { table: "pg_namespace", columns: &["oid"], ranges: "" }]),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"explain select relname, relnamespace FROM pg_catalog.pg_class c 
where c.relname = 't' and c.relkind = 'r'
order by 1,2"#,
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::IndexScan { table: "pg_class", columns: &["relname", "relnamespace"], ranges: "[{[t, t], [NULL, ∞)}]" }]),
                    ..A
                },
            ],
            ..S
        },
        // Changed from the Go test: CREATE SCHEMA AUTHORIZATION requires the role to exist in Postgres.
        ScriptTest {
            name: "regression test for in-memory index corruption (caused by empty schema name)",
            set_up_script: &[
                "CREATE ROLE s1",
                "CREATE SCHEMA AUTHORIZATION s1",
                "create table idxpart (a int, b int, c text) partition by range (a);",
                "create index idxpart_idx on idxpart (a);",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "select count(*) from pg_class where relname = 'idxpart_idx';",
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("1")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
