#[test]
fn test_pg_database() {
    run_scripts(&[
        ScriptTest {
            name: "pg_database",
            set_up_script: &[
                "CREATE DATABASE test;",
                "CREATE TABLE test (pk INT primary key, v1 INT);",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT datname FROM "pg_catalog"."pg_database";"#,
                    expected: Expected::Rows {
                        columns: &[Column("datname", NAME)],
                        rows: &[
                            &[T("postgres")],
                            &[T("test")],
                            &[T("template1")],
                            &[T("template0")],
                        ],
                        tag: "SELECT 4",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT oid, datname FROM "pg_catalog"."pg_database" ORDER BY datname DESC;"#,
                    expected: Expected::Rows {
                        columns: &[Column("oid", OID), Column("datname", NAME)],
                        rows: &[
                            &[Oid(16384), T("test")],
                            &[T("1"), T("template1")],
                            &[T("4"), T("template0")],
                            &[T("5"), T("postgres")],
                        ],
                        tag: "SELECT 4",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "PG_catalog"."pg_database";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "PG_catalog.pg_database" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "pg_catalog"."PG_database";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "pg_catalog.PG_database" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT oid, datname FROM PG_catalog.pg_DATABASE ORDER BY datname ASC;",
                    expected: Expected::Rows {
                        columns: &[Column("oid", OID), Column("datname", NAME)],
                        rows: &[
                            &[T("5"), T("postgres")],
                            &[T("4"), T("template0")],
                            &[T("1"), T("template1")],
                            &[Oid(16384), T("test")],
                        ],
                        tag: "SELECT 4",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT * FROM pg_catalog.pg_database WHERE datname='test';",
                    expected: Expected::Rows {
                        columns: &[Column("oid", OID), Column("datname", NAME), Column("datdba", OID), Column("encoding", INT4), Column("datlocprovider", CHAR), Column("datistemplate", BOOL), Column("datallowconn", BOOL), Column("datconnlimit", INT4), Column("datfrozenxid", XID), Column("datminmxid", XID), Column("dattablespace", OID), Column("datcollate", TEXT), Column("datctype", TEXT), Column("daticulocale", TEXT), Column("datcollversion", TEXT), Column("datacl", ACLITEM_ARRAY)],
                        rows: &[
                            &[Oid(16384), T("test"), T("10"), T("6"), T("c"), T("f"), T("t"), T("-1"), T("717"), T("1"), T("1663"), T("C"), T("C"), Null, Null, Null],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

