#[test]
fn test_pg_index() {
    run_scripts(&[
        ScriptTest {
            name: "pg_index",
            set_up_script: &[
                "CREATE SCHEMA testschema;",
                "SET search_path TO testschema;",
                "CREATE TABLE testing (pk INT primary key, v1 INT UNIQUE);",
                "CREATE TABLE testing2 (pk INT, v1 INT, PRIMARY KEY (pk, v1));",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT i.* from pg_class c
						JOIN pg_index i ON c.oid = i.indexrelid
						JOIN pg_namespace n ON c.relnamespace = n.oid
						WHERE n.nspname = 'testschema' and left(c.relname, 5) <> 'dolt_'
						ORDER BY 1;"#,
                    expected: Expected::Rows {
                        columns: &[Column("indexrelid", OID), Column("indrelid", OID), Column("indnatts", INT2), Column("indnkeyatts", INT2), Column("indisunique", BOOL), Column("indnullsnotdistinct", BOOL), Column("indisprimary", BOOL), Column("indisexclusion", BOOL), Column("indimmediate", BOOL), Column("indisclustered", BOOL), Column("indisvalid", BOOL), Column("indcheckxmin", BOOL), Column("indisready", BOOL), Column("indislive", BOOL), Column("indisreplident", BOOL), Column("indkey", INT2VECTOR), Column("indcollation", OIDVECTOR), Column("indclass", OIDVECTOR), Column("indoption", INT2VECTOR), Column("indexprs", PG_NODE_TREE), Column("indpred", PG_NODE_TREE)],
                        rows: &[
                            &[Oid(16388), Oid(16385), T("1"), T("1"), T("t"), T("f"), T("t"), T("f"), T("t"), T("f"), T("t"), T("f"), T("t"), T("t"), T("f"), T("1"), T("0"), T("1978"), T("0"), Null, Null],
                            &[Oid(16390), Oid(16385), T("1"), T("1"), T("t"), T("f"), T("f"), T("f"), T("t"), T("f"), T("t"), T("f"), T("t"), T("t"), T("f"), T("2"), T("0"), T("1978"), T("0"), Null, Null],
                            &[Oid(16395), Oid(16392), T("2"), T("2"), T("t"), T("f"), T("t"), T("f"), T("t"), T("f"), T("t"), T("f"), T("t"), T("t"), T("f"), T("1 2"), T("0 0"), T("1978 1978"), T("0 0"), Null, Null],
                        ],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "PG_catalog"."pg_index";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "PG_catalog.pg_index" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "pg_catalog"."PG_index";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "pg_catalog.PG_index" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT i.indexrelid from pg_class c JOIN PG_catalog.pg_INDEX i ON c.oid = i.indexrelid JOIN pg_namespace n ON c.relnamespace = n.oid WHERE n.nspname = 'testschema' and left(c.relname, 5) <> 'dolt_' ORDER BY 1;",
                    expected: Expected::Rows {
                        columns: &[Column("indexrelid", OID)],
                        rows: &[
                            &[Oid(16388)],
                            &[Oid(16390)],
                            &[Oid(16395)],
                        ],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT i.indexrelid, i.indrelid, c.relname, t.relname  FROM pg_catalog.pg_index i JOIN pg_catalog.pg_class c ON i.indexrelid = c.oid JOIN pg_catalog.pg_class t ON i.indrelid = t.oid JOIN pg_namespace n ON t.relnamespace = n.oid WHERE n.nspname = 'testschema' and left(c.relname, 5) <> 'dolt_'",
                    expected: Expected::Rows {
                        columns: &[Column("indexrelid", OID), Column("indrelid", OID), Column("relname", NAME), Column("relname", NAME)],
                        rows: &[
                            &[Oid(16388), Oid(16385), T("testing_pkey"), T("testing")],
                            &[Oid(16390), Oid(16385), T("testing_v1_key"), T("testing")],
                            &[Oid(16395), Oid(16392), T("testing2_pkey"), T("testing2")],
                        ],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT unnest(indoption) FROM pg_index LIMIT 1;",
                    expected: Expected::Rows {
                        columns: &[Column("unnest", INT2)],
                        rows: &[
                            &[T("0")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "pg_index indoption has one entry per key column",
            set_up_script: &[
                "CREATE TABLE bug13 (a integer, b integer);",
                "CREATE INDEX bug13_ab ON bug13 (a, b);",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT indkey, indoption, array_length(indkey, 1), array_length(indoption, 1)
						FROM pg_index WHERE indexrelid = 'bug13_ab'::regclass;"#,
                    expected: Expected::Rows {
                        columns: &[Column("indkey", INT2VECTOR), Column("indoption", INT2VECTOR), Column("array_length", INT4), Column("array_length", INT4)],
                        rows: &[
                            &[T("1 2"), T("0 0"), T("2"), T("2")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT indnatts, indnkeyatts, array_length(indcollation, 1), array_length(indclass, 1)
						FROM pg_index WHERE indexrelid = 'bug13_ab'::regclass;"#,
                    expected: Expected::Rows {
                        columns: &[Column("indnatts", INT2), Column("indnkeyatts", INT2), Column("array_length", INT4), Column("array_length", INT4)],
                        rows: &[
                            &[T("2"), T("2"), T("2"), T("2")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT unnest(indoption) FROM pg_index WHERE indexrelid = 'bug13_ab'::regclass;",
                    expected: Expected::Rows {
                        columns: &[Column("unnest", INT2)],
                        rows: &[
                            &[T("0")],
                            &[T("0")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_pg_index_indexes() {
    run_scripts(&[
        ScriptTest {
            name: "pg_index index lookup",
            set_up_script: &[
                "create table t1 (a int primary key, b int not null)",
                "create table t2 (c int primary key, d int not null)",
                "create index on t2 (d)",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT * FROM pg_catalog.pg_index i 
WHERE i.indrelid = 1496157034 order by 1"#,
                    expected: Expected::Rows {
                        columns: &[Column("indexrelid", OID), Column("indrelid", OID), Column("indnatts", INT2), Column("indnkeyatts", INT2), Column("indisunique", BOOL), Column("indnullsnotdistinct", BOOL), Column("indisprimary", BOOL), Column("indisexclusion", BOOL), Column("indimmediate", BOOL), Column("indisclustered", BOOL), Column("indisvalid", BOOL), Column("indcheckxmin", BOOL), Column("indisready", BOOL), Column("indislive", BOOL), Column("indisreplident", BOOL), Column("indkey", INT2VECTOR), Column("indcollation", OIDVECTOR), Column("indclass", OIDVECTOR), Column("indoption", INT2VECTOR), Column("indexprs", PG_NODE_TREE), Column("indpred", PG_NODE_TREE)],
                        rows: &[],
                        tag: "SELECT 0",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT c.relname, c2.relname FROM pg_catalog.pg_index i
         join pg_class c on i.indrelid = c.oid
         join pg_class c2 on i.indexrelid = c2.oid
WHERE c.relname = 't2' order by 1,2"#,
                    expected: Expected::Rows {
                        columns: &[Column("relname", NAME), Column("relname", NAME)],
                        rows: &[
                            &[T("t2"), T("t2_d_idx")],
                            &[T("t2"), T("t2_pkey")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT i.indrelid FROM pg_catalog.pg_index i 
WHERE i.indexrelid = (SELECT c.oid FROM pg_catalog.pg_class c WHERE c.relname = 't2_pkey')
ORDER BY 1;"#,
                    expected: Expected::Rows {
                        columns: &[Column("indrelid", OID)],
                        rows: &[
                            &[Oid(16389)],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT count(*) FROM pg_catalog.pg_index i 
WHERE i.indrelid = 1496157034"#,
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("0")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT i.indisprimary FROM pg_catalog.pg_index i 
WHERE i.indrelid = 1496157034 AND i.indisprimary = true
ORDER BY 1;"#,
                    expected: Expected::Rows {
                        columns: &[Column("indisprimary", BOOL)],
                        rows: &[],
                        tag: "SELECT 0",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT COUNT(*) FROM pg_catalog.pg_index i 
WHERE i.indrelid IN (1496157033, 1496157034)"#,
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("0")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"EXPLAIN SELECT i.indrelid FROM pg_catalog.pg_index i 
WHERE i.indexrelid = (SELECT c.oid FROM pg_catalog.pg_class c WHERE c.relname = 't1_pkey')
ORDER BY 1;"#,
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::IndexScan { table: "pg_class", columns: &["relname", "relnamespace"], ranges: "[{[t1_pkey, t1_pkey], [NULL, ∞)}]" }, PlanFact::FullScan { table: "pg_index" }]),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"EXPLAIN SELECT COUNT(*) FROM pg_catalog.pg_index i 
WHERE i.indrelid = 1496157034 ORDER BY 1"#,
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::IndexScan { table: "pg_index", columns: &["indrelid"], ranges: r#"[{[{Table:["public","t2"]}, {Table:["public","t2"]}]}]"# }]),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"EXPLAIN SELECT COUNT(*) FROM pg_catalog.pg_index i 
WHERE i.indrelid IN (1496157033, 1496157034) ORDER BY 1"#,
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::IndexScan { table: "pg_index", columns: &["indrelid"], ranges: r#"[{[{OID:["1496157033"]}, {OID:["1496157033"]}]}, {[{Table:["public","t2"]}, {Table:["public","t2"]}]}]"# }]),
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_pg_indexes() {
    run_scripts(&[
        ScriptTest {
            name: "pg_indexes",
            set_up_script: &[
                "CREATE SCHEMA testschema;",
                "SET search_path TO testschema;",
                "CREATE TABLE testing (pk INT primary key, v1 INT UNIQUE);",
                "CREATE TABLE testing2 (pk INT, v1 INT, PRIMARY KEY (pk, v1));",
                "CREATE INDEX my_index ON testing2(v1);",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "pg_catalog"."pg_indexes" where schemaname = 'testschema';"#,
                    expected: Expected::Rows {
                        columns: &[Column("schemaname", NAME), Column("tablename", NAME), Column("indexname", NAME), Column("tablespace", NAME), Column("indexdef", TEXT)],
                        rows: &[
                            &[T("testschema"), T("testing"), T("testing_pkey"), Null, T("CREATE UNIQUE INDEX testing_pkey ON testschema.testing USING btree (pk)")],
                            &[T("testschema"), T("testing"), T("testing_v1_key"), Null, T("CREATE UNIQUE INDEX testing_v1_key ON testschema.testing USING btree (v1)")],
                            &[T("testschema"), T("testing2"), T("testing2_pkey"), Null, T("CREATE UNIQUE INDEX testing2_pkey ON testschema.testing2 USING btree (pk, v1)")],
                            &[T("testschema"), T("testing2"), T("my_index"), Null, T("CREATE INDEX my_index ON testschema.testing2 USING btree (v1)")],
                        ],
                        tag: "SELECT 4",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "PG_catalog"."pg_indexes";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "PG_catalog.pg_indexes" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "pg_catalog"."PG_indexes";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "pg_catalog.PG_indexes" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT indexname FROM PG_catalog.pg_INDEXES where schemaname='testschema' ORDER BY indexname;",
                    expected: Expected::Rows {
                        columns: &[Column("indexname", NAME)],
                        rows: &[
                            &[T("my_index")],
                            &[T("testing2_pkey")],
                            &[T("testing_pkey")],
                            &[T("testing_v1_key")],
                        ],
                        tag: "SELECT 4",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

