#[test]
fn test_pg_namespace() {
    run_scripts(&[
        ScriptTest {
            name: "pg_namespace",
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "pg_catalog"."pg_namespace" ORDER BY nspname;"#,
                    expected: Expected::Rows {
                        columns: &[Column("oid", OID), Column("nspname", NAME), Column("nspowner", OID), Column("nspacl", ACLITEM_ARRAY)],
                        rows: &[
                            &[T("13679"), T("information_schema"), T("10"), T("{postgres=UC/postgres,=U/postgres}")],
                            &[T("11"), T("pg_catalog"), T("10"), T("{postgres=UC/postgres,=U/postgres}")],
                            &[T("99"), T("pg_toast"), T("10"), Null],
                            &[T("2200"), T("public"), T("6171"), T("{pg_database_owner=UC/pg_database_owner,=U/pg_database_owner}")],
                        ],
                        tag: "SELECT 4",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "PG_catalog"."pg_namespace";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "PG_catalog.pg_namespace" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "pg_catalog"."PG_namespace";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "pg_catalog.PG_namespace" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT nspname FROM PG_catalog.pg_NAMESPACE ORDER BY nspname;",
                    expected: Expected::Rows {
                        columns: &[Column("nspname", NAME)],
                        rows: &[
                            &[T("information_schema")],
                            &[T("pg_catalog")],
                            &[T("pg_toast")],
                            &[T("public")],
                        ],
                        tag: "SELECT 4",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "CREATE SCHEMA testschema;",
                    expected: Expected::Tag("CREATE SCHEMA"),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "pg_catalog"."pg_namespace" ORDER BY nspname;"#,
                    expected: Expected::Rows {
                        columns: &[Column("oid", OID), Column("nspname", NAME), Column("nspowner", OID), Column("nspacl", ACLITEM_ARRAY)],
                        rows: &[
                            &[T("13679"), T("information_schema"), T("10"), T("{postgres=UC/postgres,=U/postgres}")],
                            &[T("11"), T("pg_catalog"), T("10"), T("{postgres=UC/postgres,=U/postgres}")],
                            &[T("99"), T("pg_toast"), T("10"), Null],
                            &[T("2200"), T("public"), T("6171"), T("{pg_database_owner=UC/pg_database_owner,=U/pg_database_owner}")],
                            &[Oid(16384), T("testschema"), T("10"), Null],
                        ],
                        tag: "SELECT 5",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT oid, nspname FROM "pg_catalog"."pg_namespace" ORDER BY nspname;"#,
                    expected: Expected::Rows {
                        columns: &[Column("oid", OID), Column("nspname", NAME)],
                        rows: &[
                            &[T("13679"), T("information_schema")],
                            &[T("11"), T("pg_catalog")],
                            &[T("99"), T("pg_toast")],
                            &[T("2200"), T("public")],
                            &[Oid(16384), T("testschema")],
                        ],
                        tag: "SELECT 5",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT nspname FROM "pg_catalog"."pg_namespace" WHERE oid = 11;"#,
                    expected: Expected::Rows {
                        columns: &[Column("nspname", NAME)],
                        rows: &[
                            &[T("pg_catalog")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT oid FROM "pg_catalog"."pg_namespace" WHERE nspname = 'public';"#,
                    expected: Expected::Rows {
                        columns: &[Column("oid", OID)],
                        rows: &[
                            &[T("2200")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "regnamespace",
            set_up_script: &[
                "CREATE SCHEMA s3334;",
                "CREATE TABLE t3334 (id INT PRIMARY KEY, ns REGNAMESPACE);",
                "INSERT INTO t3334 VALUES (1, 'public'), (2, 's3334');",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT 'public'::regnamespace;",
                    expected: Expected::Rows {
                        columns: &[Column("regnamespace", REGNAMESPACE)],
                        rows: &[
                            &[T("public")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT oid::regnamespace FROM pg_namespace WHERE nspname = 'public';",
                    expected: Expected::Rows {
                        columns: &[Column("oid", REGNAMESPACE)],
                        rows: &[
                            &[T("public")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT 'public'::REGNAMESPACE, 'public'::REGNAMESPACE::OID = (SELECT oid FROM pg_namespace WHERE nspname = 'public'), 's3334'::REGNAMESPACE::TEXT, to_regnamespace('s3334') IS NOT NULL, to_regnamespace('nope'), (SELECT nspname FROM pg_namespace WHERE oid = 's3334'::REGNAMESPACE);",
                    expected: Expected::Rows {
                        columns: &[Column("regnamespace", REGNAMESPACE), Column("?column?", BOOL), Column("text", TEXT), Column("?column?", BOOL), Column("to_regnamespace", REGNAMESPACE), Column("nspname", NAME)],
                        rows: &[
                            &[T("public"), T("t"), T("s3334"), T("t"), Null, T("s3334")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT relnamespace::REGNAMESPACE FROM pg_class WHERE relname = 't3334';",
                    expected: Expected::Rows {
                        columns: &[Column("relnamespace", REGNAMESPACE)],
                        rows: &[
                            &[T("public")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT typname FROM pg_type WHERE typname = 'regnamespace';",
                    expected: Expected::Rows {
                        columns: &[Column("typname", NAME)],
                        rows: &[
                            &[T("regnamespace")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT id, ns, ns::TEXT FROM t3334 ORDER BY id;",
                    expected: Expected::Rows {
                        columns: &[Column("id", INT4), Column("ns", REGNAMESPACE), Column("ns", TEXT)],
                        rows: &[
                            &[T("1"), T("public"), T("public")],
                            &[T("2"), T("s3334"), T("s3334")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT 'nope'::REGNAMESPACE;",
                    expected: Expected::Error(Diagnostic { code: "3F000", message: r#"schema "nope" does not exist"#, position: 8, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT 'a.b'::REGNAMESPACE;",
                    expected: Expected::Error(Diagnostic { code: "42602", message: "invalid name syntax", position: 8, ..E }),
                    ..A
                },
            ],
            ..S
        },
    ]);
}

