#[test]
fn test_pg_opclass() {
    run_scripts(&[
        ScriptTest {
            name: "pg_opclass",
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT opc.opcname, am.amname, opf.opfname, t.typname, opc.opcdefault
							FROM pg_catalog.pg_opclass opc
							JOIN pg_catalog.pg_am am ON opc.opcmethod = am.oid
							JOIN pg_catalog.pg_opfamily opf ON opc.opcfamily = opf.oid
							JOIN pg_catalog.pg_type t ON opc.opcintype = t.oid
							WHERE opc.opcname IN ('int2_ops', 'int4_ops', 'int8_ops') AND am.amname = 'btree'
							ORDER BY opc.opcname;"#,
                    expected: Expected::Rows {
                        columns: &[Column("opcname", NAME), Column("amname", NAME), Column("opfname", NAME), Column("typname", NAME), Column("opcdefault", BOOL)],
                        rows: &[
                            &[T("int2_ops"), T("btree"), T("integer_ops"), T("int2"), T("t")],
                            &[T("int4_ops"), T("btree"), T("integer_ops"), T("int4"), T("t")],
                            &[T("int8_ops"), T("btree"), T("integer_ops"), T("int8"), T("t")],
                        ],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT opc.opcname, t.typname, opc.opcdefault
							FROM pg_catalog.pg_opclass opc
							JOIN pg_catalog.pg_am am ON opc.opcmethod = am.oid
							JOIN pg_catalog.pg_type t ON opc.opcintype = t.oid
							WHERE opc.opcname = 'varchar_ops' AND am.amname = 'hash';"#,
                    expected: Expected::Rows {
                        columns: &[Column("opcname", NAME), Column("typname", NAME), Column("opcdefault", BOOL)],
                        rows: &[
                            &[T("varchar_ops"), T("text"), T("f")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT opf.oid, opc.opcname, t.typname, opc.opcdefault
							FROM pg_catalog.pg_opclass opc
							JOIN pg_catalog.pg_am am ON opc.opcmethod = am.oid
							JOIN pg_catalog.pg_opfamily opf ON opc.opcfamily = opf.oid
							JOIN pg_catalog.pg_type t ON opc.opcintype = t.oid
							WHERE opc.opcname LIKE '%pattern%' AND am.amname = 'hash'
							ORDER BY opc.opcname;"#,
                    expected: Expected::Rows {
                        columns: &[Column("oid", OID), Column("opcname", NAME), Column("typname", NAME), Column("opcdefault", BOOL)],
                        rows: &[
                            &[T("2231"), T("bpchar_pattern_ops"), T("bpchar"), T("f")],
                            &[T("2229"), T("text_pattern_ops"), T("text"), T("f")],
                            &[T("2229"), T("varchar_pattern_ops"), T("text"), T("f")],
                        ],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT count(*) > 40 FROM "pg_catalog"."pg_opclass";"#,
                    expected: Expected::Rows {
                        columns: &[Column("?column?", BOOL)],
                        rows: &[
                            &[T("t")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT oid, opfname FROM pg_opfamily f
							WHERE NOT EXISTS (SELECT 1 FROM pg_opclass WHERE opcfamily = f.oid);"#,
                    expected: Expected::Rows {
                        columns: &[Column("oid", OID), Column("opfname", NAME)],
                        rows: &[],
                        tag: "SELECT 0",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "PG_catalog"."pg_opclass";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "PG_catalog.pg_opclass" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "pg_catalog"."PG_opclass";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "pg_catalog.PG_opclass" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT opcname FROM PG_catalog.pg_OPCLASS WHERE opcname = 'uuid_ops' ORDER BY opcname;",
                    expected: Expected::Rows {
                        columns: &[Column("opcname", NAME)],
                        rows: &[
                            &[T("uuid_ops")],
                            &[T("uuid_ops")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

