#[test]
fn test_pg_opfamily() {
    run_scripts(&[
        ScriptTest {
            name: "pg_opfamily",
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT opf.oid, opf.opfname, am.amname
							FROM pg_catalog.pg_opfamily opf
							JOIN pg_catalog.pg_am am ON opf.opfmethod = am.oid
							WHERE opf.opfname = 'integer_ops'
							ORDER BY opf.oid;"#,
                    expected: Expected::Rows {
                        columns: &[Column("oid", OID), Column("opfname", NAME), Column("amname", NAME)],
                        rows: &[
                            &[T("1976"), T("integer_ops"), T("btree")],
                            &[T("1977"), T("integer_ops"), T("hash")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT oid, opfname FROM "pg_catalog"."pg_opfamily" WHERE opfname IN ('text_ops', 'datetime_ops') ORDER BY oid;"#,
                    expected: Expected::Rows {
                        columns: &[Column("oid", OID), Column("opfname", NAME)],
                        rows: &[
                            &[T("434"), T("datetime_ops")],
                            &[T("1994"), T("text_ops")],
                            &[T("1995"), T("text_ops")],
                            &[T("4017"), T("text_ops")],
                        ],
                        tag: "SELECT 4",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT count(*) > 30 FROM "pg_catalog"."pg_opfamily";"#,
                    expected: Expected::Rows {
                        columns: &[Column("?column?", BOOL)],
                        rows: &[
                            &[T("t")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "PG_catalog"."pg_opfamily";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "PG_catalog.pg_opfamily" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "pg_catalog"."PG_opfamily";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "pg_catalog.PG_opfamily" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT opfname FROM PG_catalog.pg_OPFAMILY WHERE opfname = 'uuid_ops' ORDER BY opfname;",
                    expected: Expected::Rows {
                        columns: &[Column("opfname", NAME)],
                        rows: &[
                            &[T("uuid_ops")],
                            &[T("uuid_ops")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

