#[test]
fn test_pg_statistic_ext() {
    run_scripts(&[
        ScriptTest {
            name: "pg_statistic_ext",
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "pg_catalog"."pg_statistic_ext";"#,
                    expected: Expected::Rows {
                        columns: &[Column("oid", OID), Column("stxrelid", OID), Column("stxname", NAME), Column("stxnamespace", OID), Column("stxowner", OID), Column("stxstattarget", INT4), Column("stxkeys", INT2VECTOR), Column("stxkind", CHAR_ARRAY), Column("stxexprs", PG_NODE_TREE)],
                        rows: &[],
                        tag: "SELECT 0",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "PG_catalog"."pg_statistic_ext";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "PG_catalog.pg_statistic_ext" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "pg_catalog"."PG_statistic_ext";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "pg_catalog.PG_statistic_ext" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT stxname FROM PG_catalog.pg_STATISTIC_EXT ORDER BY stxname;",
                    expected: Expected::Rows {
                        columns: &[Column("stxname", NAME)],
                        rows: &[],
                        tag: "SELECT 0",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

