#[test]
fn test_pg_tables() {
    run_scripts(&[
        ScriptTest {
            name: "pg_tables",
            set_up_script: &[
                "create table t1 (pk int primary key, v1 int);",
                "create table t2 (pk int primary key, v1 int);",
                "CREATE SCHEMA testschema;",
                "SET search_path TO testschema;",
                "CREATE TABLE testing (pk INT primary key, v1 INT);",
                "CREATE SCHEMA testschema2;",
                "SET search_path TO testschema2;",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "pg_catalog"."pg_tables" WHERE tablename='testing' order by 1;"#,
                    expected: Expected::Rows {
                        columns: &[Column("schemaname", NAME), Column("tablename", NAME), Column("tableowner", NAME), Column("tablespace", NAME), Column("hasindexes", BOOL), Column("hasrules", BOOL), Column("hastriggers", BOOL), Column("rowsecurity", BOOL)],
                        rows: &[
                            &[T("testschema"), T("testing"), T("postgres"), Null, T("t"), T("f"), T("f"), T("f")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT count(*) FROM "pg_catalog"."pg_tables" WHERE schemaname='pg_catalog';"#,
                    expected: Expected::Rows {
                        columns: &[Column("count", INT8)],
                        rows: &[
                            &[T("64")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "PG_catalog"."pg_tables";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "PG_catalog.pg_tables" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "pg_catalog"."PG_tables";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "pg_catalog.PG_tables" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT schemaname, tablename FROM PG_catalog.pg_TABLES WHERE schemaname not in ('information_schema', 'dolt', 'public') ORDER BY tablename DESC LIMIT 3;",
                    expected: Expected::Rows {
                        columns: &[Column("schemaname", NAME), Column("tablename", NAME)],
                        rows: &[
                            &[T("testschema"), T("testing")],
                            &[T("pg_catalog"), T("pg_user_mapping")],
                            &[T("pg_catalog"), T("pg_type")],
                        ],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT schemaname, tablename FROM PG_catalog.pg_TABLES WHERE schemaname  ='public' ORDER BY tablename;",
                    expected: Expected::Rows {
                        columns: &[Column("schemaname", NAME), Column("tablename", NAME)],
                        rows: &[
                            &[T("public"), T("t1")],
                            &[T("public"), T("t2")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

