#[test]
fn test_pg_trigger() {
    run_scripts(&[
        ScriptTest {
            name: "pg_trigger",
            set_up_script: &[
                "CREATE TABLE test (pk INT PRIMARY KEY, v1 TEXT);",
                r#"CREATE FUNCTION trigger_func() RETURNS TRIGGER AS $$
				BEGIN
					RETURN NEW;
				END;
				$$ LANGUAGE plpgsql;"#,
                "CREATE TRIGGER test_trigger BEFORE INSERT ON test FOR EACH ROW EXECUTE FUNCTION trigger_func();",
                "CREATE TRIGGER test_trigger2 AFTER UPDATE OR DELETE ON test FOR EACH ROW EXECUTE FUNCTION trigger_func();",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT tgname, tgtype, tgenabled, tgisinternal, tgdeferrable, tginitdeferred, tgnargs, tgqual, tgoldtable, tgnewtable FROM "pg_catalog"."pg_trigger" ORDER BY tgname;"#,
                    expected: Expected::Rows {
                        columns: &[Column("tgname", NAME), Column("tgtype", INT2), Column("tgenabled", CHAR), Column("tgisinternal", BOOL), Column("tgdeferrable", BOOL), Column("tginitdeferred", BOOL), Column("tgnargs", INT2), Column("tgqual", PG_NODE_TREE), Column("tgoldtable", NAME), Column("tgnewtable", NAME)],
                        rows: &[
                            &[T("test_trigger"), T("7"), T("O"), T("f"), T("f"), T("f"), T("0"), Null, Null, Null],
                            &[T("test_trigger2"), T("25"), T("O"), T("f"), T("f"), T("f"), T("0"), Null, Null, Null],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT c.relname, t.tgname FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_class c ON t.tgrelid = c.oid ORDER BY t.tgname;",
                    expected: Expected::Rows {
                        columns: &[Column("relname", NAME), Column("tgname", NAME)],
                        rows: &[
                            &[T("test"), T("test_trigger")],
                            &[T("test"), T("test_trigger2")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT p.proname FROM pg_catalog.pg_trigger t JOIN pg_catalog.pg_proc p ON t.tgfoid = p.oid WHERE t.tgname = 'test_trigger';",
                    expected: Expected::Rows {
                        columns: &[Column("proname", NAME)],
                        rows: &[
                            &[T("trigger_func")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "PG_catalog"."pg_trigger";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "PG_catalog.pg_trigger" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "pg_catalog"."PG_trigger";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "pg_catalog.PG_trigger" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT tgname FROM PG_catalog.pg_TRIGGER ORDER BY tgname;",
                    expected: Expected::Rows {
                        columns: &[Column("tgname", NAME)],
                        rows: &[
                            &[T("test_trigger")],
                            &[T("test_trigger2")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

