#[test]
fn test_pg_type_indexes() {
    run_scripts(&[
        ScriptTest {
            name: "pg_type_oid_index",
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT typname FROM pg_catalog.pg_type WHERE oid = 23 ORDER BY 1;",
                    expected: Expected::Rows {
                        columns: &[Column("typname", NAME)],
                        rows: &[
                            &[T("int4")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT typname FROM pg_catalog.pg_type WHERE oid = '23' ORDER BY 1;",
                    expected: Expected::Rows {
                        columns: &[Column("typname", NAME)],
                        rows: &[
                            &[T("int4")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT typname FROM pg_catalog.pg_type WHERE oid > 22 AND oid < 25 ORDER BY typname;",
                    expected: Expected::Rows {
                        columns: &[Column("typname", NAME)],
                        rows: &[
                            &[T("int4")],
                            &[T("regproc")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT typname FROM pg_catalog.pg_type WHERE oid IN (23, 25) ORDER BY typname;",
                    expected: Expected::Rows {
                        columns: &[Column("typname", NAME)],
                        rows: &[
                            &[T("int4")],
                            &[T("text")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT typname FROM pg_catalog.pg_type ORDER BY oid LIMIT 1;",
                    expected: Expected::Rows {
                        columns: &[Column("typname", NAME)],
                        rows: &[
                            &[T("bool")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "EXPLAIN SELECT typname FROM pg_catalog.pg_type WHERE oid = 23 ORDER BY 1;",
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::IndexScan { table: "pg_type", columns: &["oid"], ranges: r#"[{[{Type:["pg_catalog","int4"]}, {Type:["pg_catalog","int4"]}]}]"# }]),
                    ..A
                },
                ScriptTestAssertion {
                    query: "EXPLAIN SELECT typname FROM pg_catalog.pg_type WHERE oid > 22 AND oid < 25 ORDER BY 1;",
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::IndexScan { table: "pg_type", columns: &["oid"], ranges: r#"[{({Type:["pg_catalog","int2vector"]}, {Type:["pg_catalog","text"]})}]"# }]),
                    ..A
                },
                ScriptTestAssertion {
                    query: "EXPLAIN SELECT typname FROM pg_catalog.pg_type WHERE oid IN (23, 25) ORDER BY typname;",
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::IndexScan { table: "pg_type", columns: &["oid"], ranges: r#"[{[{Type:["pg_catalog","int4"]}, {Type:["pg_catalog","int4"]}]}, {[{Type:["pg_catalog","text"]}, {Type:["pg_catalog","text"]}]}]"# }]),
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "pg_type_typname_nsp_index",
            assertions: &[
                ScriptTestAssertion {
                    query: "SELECT oid FROM pg_catalog.pg_type WHERE typname = 'int4' AND typnamespace = 11 ORDER BY 1;",
                    expected: Expected::Rows {
                        columns: &[Column("oid", OID)],
                        rows: &[
                            &[T("23")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT typname FROM pg_catalog.pg_type WHERE typname > 'int2' AND typname < 'int8' AND typnamespace = 11 ORDER BY 1;",
                    expected: Expected::Rows {
                        columns: &[Column("typname", NAME)],
                        rows: &[
                            &[T("int2vector")],
                            &[T("int4")],
                            &[T("int4multirange")],
                            &[T("int4range")],
                        ],
                        tag: "SELECT 4",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT typname FROM pg_catalog.pg_type WHERE typname >= 'int2' AND typname <= 'int4' AND typnamespace = 11 ORDER BY 1;",
                    expected: Expected::Rows {
                        columns: &[Column("typname", NAME)],
                        rows: &[
                            &[T("int2")],
                            &[T("int2vector")],
                            &[T("int4")],
                        ],
                        tag: "SELECT 3",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT typname FROM pg_catalog.pg_type WHERE typname > 'int2' AND typname <= 'int4' AND typnamespace = 11 ORDER BY 1;",
                    expected: Expected::Rows {
                        columns: &[Column("typname", NAME)],
                        rows: &[
                            &[T("int2vector")],
                            &[T("int4")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT typname FROM pg_catalog.pg_type WHERE typname >= 'int4' AND typname <= 'int4' AND typnamespace = 11 ORDER BY 1;",
                    expected: Expected::Rows {
                        columns: &[Column("typname", NAME)],
                        rows: &[
                            &[T("int4")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "EXPLAIN SELECT oid FROM pg_catalog.pg_type WHERE typname = 'int4' AND typnamespace = 11 ORDER BY 1;",
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::IndexScan { table: "pg_type", columns: &["typname", "typnamespace"], ranges: r#"[{[int4, int4], [{Namespace:["pg_catalog"]}, {Namespace:["pg_catalog"]}]}]"# }]),
                    ..A
                },
                ScriptTestAssertion {
                    query: "EXPLAIN SELECT typname FROM pg_catalog.pg_type WHERE typname > 'int2' AND typname < 'int8' AND typnamespace = 11 ORDER BY 1;",
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::IndexScan { table: "pg_type", columns: &["typname", "typnamespace"], ranges: r#"[{(int2, int8), [{Namespace:["pg_catalog"]}, {Namespace:["pg_catalog"]}]}]"# }]),
                    ..A
                },
            ],
            ..S
        },
        ScriptTest {
            name: "join on pg_type using index",
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT t.typname, n.nspname
  FROM pg_catalog.pg_type t
  JOIN pg_catalog.pg_namespace n ON t.typnamespace = n.oid
  WHERE t.typname = 'int4'
  ORDER BY 1;"#,
                    expected: Expected::Rows {
                        columns: &[Column("typname", NAME), Column("nspname", NAME)],
                        rows: &[
                            &[T("int4"), T("pg_catalog")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"EXPLAIN SELECT t.typname, n.nspname
								FROM pg_catalog.pg_type t
								JOIN pg_catalog.pg_namespace n ON t.typnamespace = n.oid
					   			WHERE t.typname = 'int4'
								ORDER BY 1;"#,
                    expected: Expected::Plan(&[PlanFact::Sort, PlanFact::Join { kind: "LookupJoin", left: "pg_type", right: "pg_namespace" }, PlanFact::IndexScan { table: "pg_type", columns: &["typname", "typnamespace"], ranges: "[{[int4, int4], [NULL, ∞)}]" }, PlanFact::IndexScan { table: "pg_namespace", columns: &["oid"], ranges: "" }]),
                    ..A
                },
            ],
            ..S
        },
    ]);
}

#[test]
fn test_pg_user() {
    run_scripts(&[
        ScriptTest {
            name: "pg_user",
            set_up_script: &[
                "CREATE USER user_login PASSWORD 'pwd123' CREATEDB;",
                "CREATE ROLE user_nologin NOLOGIN;",
            ],
            assertions: &[
                ScriptTestAssertion {
                    query: r#"SELECT usename, usecreatedb, usesuper, userepl, usebypassrls, passwd, valuntil, useconfig FROM "pg_catalog"."pg_user" ORDER BY usename;"#,
                    expected: Expected::Rows {
                        columns: &[Column("usename", NAME), Column("usecreatedb", BOOL), Column("usesuper", BOOL), Column("userepl", BOOL), Column("usebypassrls", BOOL), Column("passwd", TEXT), Column("valuntil", TIMESTAMPTZ), Column("useconfig", TEXT_ARRAY)],
                        rows: &[
                            &[T("postgres"), T("t"), T("t"), T("t"), T("t"), T("********"), Null, Null],
                            &[T("user_login"), T("t"), T("f"), T("f"), T("f"), T("********"), Null, Null],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT a.rolname FROM pg_catalog.pg_user u JOIN pg_catalog.pg_authid a ON u.usesysid = a.oid WHERE u.usename = 'user_login';",
                    expected: Expected::Rows {
                        columns: &[Column("rolname", NAME)],
                        rows: &[
                            &[T("user_login")],
                        ],
                        tag: "SELECT 1",
                    },
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "PG_catalog"."pg_user";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "PG_catalog.pg_user" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: r#"SELECT * FROM "pg_catalog"."PG_user";"#,
                    expected: Expected::Error(Diagnostic { code: "42P01", message: r#"relation "pg_catalog.PG_user" does not exist"#, position: 15, ..E }),
                    ..A
                },
                ScriptTestAssertion {
                    query: "SELECT usename FROM PG_catalog.pg_USER ORDER BY usename;",
                    expected: Expected::Rows {
                        columns: &[Column("usename", NAME)],
                        rows: &[
                            &[T("postgres")],
                            &[T("user_login")],
                        ],
                        tag: "SELECT 2",
                    },
                    ..A
                },
            ],
            ..S
        },
    ]);
}

